from unittest.mock import AsyncMock

import pytest

from voice_agent.schemas.call_script import JobContext
from voice_agent.schemas.candidate_datapoint import CandidateDatapointDefinition
from voice_agent.schemas.task_orchestrator import OrchestratorTaskAgentContext
from voice_agent.schemas.task_orchestrator import TaskAgentHooks


@pytest.fixture
def mock_task_agent_hooks():
    """Create mock TaskAgentHooks"""
    return TaskAgentHooks(
        on_task_agent_interrupt=AsyncMock(),
        on_task_agent_finished=AsyncMock(),
        on_datapoint_collected=AsyncMock(),
        on_end_call=AsyncMock(),
    )


@pytest.fixture
def it_support_data_schemas():
    """Create IT support candidate data point schemas"""
    return {
        "years_of_it_support_experience": CandidateDatapointDefinition(
            description="Total years of experience in IT support or helpdesk roles",
            output_schema={
                "type": "object",
                "properties": {
                    "value": {"type": "number", "minimum": 0, "maximum": 50}
                },
                "required": ["value"],
            },
        ),
        "ticketing_systems_used": CandidateDatapointDefinition(
            description="List of ticketing systems the candidate has experience with",
            output_schema={
                "type": "object",
                "properties": {"value": {"type": "array", "items": {"type": "string"}}},
                "required": ["value"],
            },
        ),
        "technical_certifications": CandidateDatapointDefinition(
            description="IT certifications held by the candidate",
            output_schema={
                "type": "object",
                "properties": {"value": {"type": "array", "items": {"type": "string"}}},
                "required": ["value"],
            },
        ),
        "customer_service_rating": CandidateDatapointDefinition(
            description="Self-assessed customer service skills rating",
            output_schema={
                "type": "object",
                "properties": {
                    "value": {"type": "number", "minimum": 1, "maximum": 10}
                },
                "required": ["value"],
            },
        ),
        "remote_troubleshooting_experience": CandidateDatapointDefinition(
            description="Experience with remote desktop and troubleshooting tools",
            output_schema={
                "type": "object",
                "properties": {"value": {"type": "boolean"}},
                "required": ["value"],
            },
        ),
        "shift_availability": CandidateDatapointDefinition(
            description="Available shifts the candidate can work",
            output_schema={
                "type": "object",
                "properties": {
                    "value": {
                        "type": "object",
                        "properties": {
                            "morning": {"type": "boolean"},
                            "evening": {"type": "boolean"},
                            "night": {"type": "boolean"},
                            "weekend": {"type": "boolean"},
                        },
                    }
                },
                "required": ["value"],
            },
        ),
        "expected_hourly_rate": CandidateDatapointDefinition(
            description="Expected hourly rate in USD",
            output_schema={
                "type": "object",
                "properties": {
                    "value": {"type": "number", "minimum": 15, "maximum": 50}
                },
                "required": ["value"],
            },
        ),
    }


@pytest.fixture
def orchestrator_context(mock_task_agent_hooks, it_support_data_schemas):
    """Create OrchestratorTaskAgentContext for IT support scenario"""
    return OrchestratorTaskAgentContext(
        task_agent_hooks=mock_task_agent_hooks,
        job_details=JobContext(
            title="IT Call Support Operator",
            description="Provide technical support to customers via phone, chat, and email.",
            company="TechSupport Solutions Inc.",
            location="Remote (USA)",
        ),
        candidate_data_point_schemas=it_support_data_schemas,
        outstanding_task_ids=["ticketing_systems", "customer_service"],
        in_progress_task_ids=["experience_qualification"],
        completed_task_ids=["greeting_node"],
        chat_ctx=None,
    )

        instructions=f"end the call gracefully due to {self.session.userdata.current_agent_interruption.interrupt_note}"
    )
    self.session.userdata.current_agent_interruption = None
else:
    await self.session.generate_reply(
        instructions="Tell them that you are ending the call. Always thank them for their time."
    )
await self.orc_ctx.task_agent_hooks.on_end_call("Closer Task Agent Completed")
